import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Group","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/group.md","filePath":"03-developer/models/group.md"}`),a={name:`03-developer/models/group.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="group" tabindex="-1">Group <a class="header-anchor" href="#group" aria-label="Permalink to “Group”">​</a></h1><p>Manages groups of posts. Each group can have a name, description, image, background, custom appearance settings, and SEO and Schema Markup information. Groups can form a tree structure through parent-child relationships and can be associated with multiple posts.</p><h2 id="groups-table" tabindex="-1"><code>groups</code> table <a class="header-anchor" href="#groups-table" aria-label="Permalink to “groups table”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique group ID</td></tr><tr><td><code>name</code></td><td>TEXT</td><td>No</td><td>Group name</td></tr><tr><td><code>slug</code></td><td>VARCHAR(128)</td><td>No</td><td>Unique text identifier used in the group URL</td></tr><tr><td><code>subtitle</code></td><td>TEXT</td><td>Yes</td><td>Group subtitle</td></tr><tr><td><code>description</code></td><td>LONGTEXT</td><td>Yes</td><td>Group description</td></tr><tr><td><code>image</code></td><td>VARCHAR(2048)</td><td>Yes</td><td>Group image</td></tr><tr><td><code>bg</code></td><td>VARCHAR(2048)</td><td>Yes</td><td>Group background image</td></tr><tr><td><code>sort</code></td><td>INT</td><td>No</td><td>Group sort value; defaults to <code>0</code></td></tr><tr><td><code>parent_id</code></td><td>INT UNSIGNED</td><td>Yes</td><td>Parent group ID; used to create a hierarchical structure</td></tr><tr><td><code>theme</code></td><td>LONGTEXT</td><td>Yes</td><td>Custom appearance settings for the group in JSON format</td></tr><tr><td><code>canonical</code></td><td>TEXT</td><td>Yes</td><td>Canonical URL for SEO</td></tr><tr><td><code>hide</code></td><td>TINYINT(1)</td><td>No</td><td>Determines whether the group is hidden in the menu as a subgroup; defaults to <code>0</code></td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Soft-deletion date</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation date</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Date of last update</td></tr><tr><td><code>default_markup</code></td><td>TEXT</td><td>Yes</td><td>Default Schema Markup for associated posts, if used by the application logic</td></tr><tr><td><code>markups</code></td><td>TEXT</td><td>Yes</td><td>Schema Markup for the group page</td></tr></tbody></table><h2 id="properties-and-methods" tabindex="-1">Properties and methods <a class="header-anchor" href="#properties-and-methods" aria-label="Permalink to “Properties and methods”">​</a></h2><h3 id="translatable" tabindex="-1"><code>$translatable</code> <a class="header-anchor" href="#translatable" aria-label="Permalink to “$translatable”">​</a></h3><p>The <code>name</code>, <code>subtitle</code>, and <code>description</code> fields support storing and retrieving translations.</p><h3 id="markupkeywords" tabindex="-1"><code>markupKeywords()</code> <a class="header-anchor" href="#markupkeywords" aria-label="Permalink to “markupKeywords()”">​</a></h3><p>Returns a set of keywords available for use in Schema Markup, along with each keyword&#39;s display title and value. These values allow information such as the application name and group name to be used in Markup templates.</p><h3 id="posts" tabindex="-1"><code>posts()</code> <a class="header-anchor" href="#posts" aria-label="Permalink to “posts()”">​</a></h3><p>Defines a <code>belongsToMany</code> relationship with the <a href="./post.html">Post</a> model and retrieves posts associated with the group through the pivot table.</p><h3 id="parent" tabindex="-1"><code>parent()</code> <a class="header-anchor" href="#parent" aria-label="Permalink to “parent()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with this model and returns the parent group through the <code>parent_id</code> field.</p><h3 id="children" tabindex="-1"><code>children()</code> <a class="header-anchor" href="#children" aria-label="Permalink to “children()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with this model and returns child groups whose <code>parent_id</code> matches the current group&#39;s ID.</p><h3 id="getroutekeyname" tabindex="-1"><code>getRouteKeyName()</code> <a class="header-anchor" href="#getroutekeyname" aria-label="Permalink to “getRouteKeyName()”">​</a></h3><p>Sets <code>slug</code> as the model&#39;s route key. As a result, Route Model Binding uses <code>slug</code> instead of <code>id</code>.</p><h3 id="author" tabindex="-1"><code>author()</code> <a class="header-anchor" href="#author" aria-label="Permalink to “author()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./user.html">User</a> model and returns the user associated with the group.</p><h3 id="imgurl" tabindex="-1"><code>imgUrl()</code> <a class="header-anchor" href="#imgurl" aria-label="Permalink to “imgUrl()”">​</a></h3><p>Returns the URL of the optimized group image from the <code>optimized/groups/</code> path. If no image is defined, the site&#39;s default logo URL is returned.</p><h3 id="imgoriginalurl" tabindex="-1"><code>imgOriginalUrl()</code> <a class="header-anchor" href="#imgoriginalurl" aria-label="Permalink to “imgOriginalUrl()”">​</a></h3><p>Returns the URL of the original group image from the <code>groups/</code> path. If no image is defined, the site&#39;s default logo URL is returned.</p><h3 id="bgurl" tabindex="-1"><code>bgUrl()</code> <a class="header-anchor" href="#bgurl" aria-label="Permalink to “bgUrl()”">​</a></h3><p>Returns the URL of the optimized group background image from the <code>optimized/groups/</code> path. If no background image is defined, the site&#39;s default logo URL is returned.</p><h3 id="bgoriginalurl" tabindex="-1"><code>bgOriginalUrl()</code> <a class="header-anchor" href="#bgoriginalurl" aria-label="Permalink to “bgOriginalUrl()”">​</a></h3><p>Returns the URL of the original group background image from the <code>groups/</code> path. If no background image is defined, the site&#39;s default logo URL is returned.</p><h3 id="attachs" tabindex="-1"><code>attachs()</code> <a class="header-anchor" href="#attachs" aria-label="Permalink to “attachs()”">​</a></h3><p>Defines a polymorphic <code>morphMany</code> relationship with the <a href="./attachment.html">Attachment</a> model and retrieves attachments associated with the group.</p><h3 id="weburl" tabindex="-1"><code>webUrl()</code> <a class="header-anchor" href="#weburl" aria-label="Permalink to “webUrl()”">​</a></h3><p>Generates the group page URL using the route named <code>client.group</code> and the <code>slug</code> value, then adjusts the URL language with <code>fixUrlLang()</code>.</p><h3 id="published-limit-10-order-id-dir-desc" tabindex="-1"><code>published($limit = 10, $order = &#39;id&#39;, $dir = &#39;DESC&#39;)</code> <a class="header-anchor" href="#published-limit-10-order-id-dir-desc" aria-label="Permalink to “published($limit = 10, $order = &#39;id&#39;, $dir = &#39;DESC&#39;)”">​</a></h3><p>Retrieves posts associated with the group that have <code>status = 1</code>. The <code>$order</code> and <code>$dir</code> parameters determine the sort order, and <code>$limit</code> determines the number of results. The output includes only the <code>title</code>, <code>slug</code>, and <code>icon</code> fields.</p><h3 id="evaluations" tabindex="-1"><code>evaluations()</code> <a class="header-anchor" href="#evaluations" aria-label="Permalink to “evaluations()”">​</a></h3><p>Retrieves evaluation criteria associated with the group. This method considers three groups of criteria:</p><ul><li>Global criteria whose <code>evaluationable_type</code> and <code>evaluationable_id</code> are both empty.</li><li>Criteria assigned to the <code>Group</code> model whose <code>evaluationable_id</code> is empty.</li><li>Criteria assigned to the current group.</li></ul><h3 id="markup" tabindex="-1"><code>markup()</code> <a class="header-anchor" href="#markup" aria-label="Permalink to “markup()”">​</a></h3><p>Displays the appropriate Schema Markup output for the group page.</p>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};